-- SQL Queries for Insureds and Agencies
-- This script retrieves data from Insureds, Agencies, and their relationships
Select * from Insureds Where FirstName like 'aaron%' -- Email like '
Select * from Agencies Where Id in ('430f50db-af57-4816-d7b9-08de3e6724e6','6cdb05c9-a61a-4283-d7ba-08de3e6724e6','a5c31b0e-87a9-498d-3e59-08de54492e08','2e87c0a8-ac74-4f15-fb23-08de38fafcf7');
Select * from Agents;
Select * from InsuredAgencies where AgencyId='6CDB05C9-A61A-4283-D7BA-08DE3E6724E6';
Select * from InsuranceApplications Where ApplicationNumber='000035-1' and Id='247ca9f0-7fcd-459b-bce1-08ddf24026a6';
Select * From Quotes;
Select * from ApplicationTypes;
Select * from ApplicationTemplates;
Select * from Policies;
Select * from CommercialGLItems;
Select * From Specialties; -- Where UISection is not null
Select * From Categories where Id ='0c355626-9dfc-4942-a0d0-6ac8673887c8'
-- Id	                                CategoryName
-- 0C355626-9DFC-4942-A0D0-6AC8673887C8	PhysicianSurgeon
-- 1F216994-30D8-4207-AAC4-3A6F8B073DAC	HealthCareProfessional
-- e1f089a7-cf19-4fc9-8319-4b43a42a259b	Facility
-- 7312294c-4d7f-4c97-81cf-7fc01d62dde0	Individual
-- e530756a-ced6-4dd0-979b-ab8e6db5c921	FacilityApp

Select I.Email, I.IsActive, I.UWVerified, IA.ApplicationNumber, IA.LicenseNumber, C.CategoryName, Case When IA.PolicyType=0 Then 'ClaimsMade' Else 'Occurrence' End As PolicyType, IA.ApplicationAnswers, IA.ModifiedDate, IA.CoverageFrom, IA.CoverageTo, -- A.Name as Agency_Name, A.UWVerified, A.IsActive, AG.FirstName, 
IA.RetroDate, IA.ApplicationStatus, IA.Is51PercentPracticeInstate, IA.IsGLCoverageElected, IA.IsPartTime, IA.IsLicenseValidated, IA.UnderwriterCredit, IA.UnderwriterDebit, IA.ProfessionalStaffDebit, IA.ApplicationAnswers, -- IA.ApplicationQuestions, IA.RatingEngineInput, IA.RatingEngineOutput, 
Q.QuoteNumber, Q.QuoteTotal, Q.CreateDate, Q.ModifiedDate, Q.PaymentType, Q.Option1DepositAmount, Q.Option2DepositAmount, Q.Option2InstallmentAmountX2, Q.Option3DepositAmount, Q.Option3FinanceCharge, Q.Option3InstallmentAmountX9, P.NewPolicyNumber, P.CreateDate, P.ModifiedDate, P.PolicyDocList
-- Select IA.ApplicationNumber, I.Email, C.CategoryName, Case When IA.PolicyType=0 Then 'ClaimsMade' Else 'Occurrence' End As PolicyType, IA.CreateDate, IA.CoverageFrom, IA.CoverageTo, null as 'PartialYear%', IA.RetroDate, IA.ApplicationStatus, IA.IsPartTime, IA.IsGLCoverageElected, Q.PaymentType, P.CreateDate, P.NewPolicyNumber, P.PolicyDocList
From Insureds I     Left Join InsuredAgencies IA1 on I.Id = IA1.InsuredId
                    -- Left Join Agencies A on A.Id = IA1.AgencyId
                    -- Left Join Agents AG on AG.AgencyId = A.Id
                    Left Join AspNetUsers U on I.UserId = U.Id
                    Left Join InsuranceApplications IA on I.Id = IA.InsuredId
                    Left Join Categories C on C.Id = IA.CategoryId
                    Left Join Quotes Q on Q.InsuranceApplicationId = IA.Id
                    Left Join Policies P on IA.Id = P.InsuranceApplicationId
                    -- Left Join InsuredDocuments D on IA.Id = D.InsuranceApplicationId
Where C.CategoryName in ('FacilityApp', 'PhysicianSurgeon','HealthCareProfessional')
     -- and IA.PolicyType = 0,1 -- ('ClaimsMade','Occurrence')
     -- and I.Email like 'luis%' -- and (AG.FirstName like 'luis%' or AG.FirstName Is Null)
      and IA.ApplicationNumber in ('000164')
     -- and IA.ApplicationStatus = 5 -- = 0 -- 
     -- and IA.CoverageTo <= '2026-05-12' -- IA.CoverageFrom >= '2026-02-12' and  -- and IA.RetroDate is null
     -- and Q.QuoteTotal >= 17532 and Q.QuoteTotal <= 17533
     -- and IA.IsGLCoverageElected = 0 -- and IA.IsPartTime=1 -- and IA.Is51PercentPracticeInstate = 1 
     -- and Q.PaymentType = 2 -- 0,1,2 
     -- and P.NewPolicyNumber IS NOT NULL and P.CreateDate>='2026-03-24 15:00:00.0000000'
     -- and P.PolicyDocList Is Not Null and (P.PolicyDocList like '%JUA75%') --  or P.PolicyDocList like '%JUA68%') --  
Order by Q.CreateDate desc, ApplicationNumber ; --  IA.CoverageTo; -- IA.RetroDate, I.Email,

Select I.UserName, I.Email, I.IsActive, I.UWVerified 
-- Select Count(CAST(I.IsActive AS INT)) as Active, Count(CAST(I.UWVerified AS INT)) as UWVerified --, Count(IA.ApplicationNumber) as QtyApplication --, IA.ApplicationStatus
From Insureds I     Left Outer Join AspNetUsers U on I.UserId = U.Id
                    Left Outer Join AspNetUserClaims C on U.Id = C.UserId
                    Left Outer Join Agencies G on C.ClaimValue = G.Id and C.ClaimType='AgencyId'
Where I.IsActive = 1
